          "detail": "太平兴国三年四月，割据漳、泉二州之平海节度使陈洪进献表纳十四县归宋；五月乙酉，入朝开封之吴越国王钱俶审时度势，上表献所辖两浙十三州、一军、八十六县、户五十五万六百八十、兵十一万五千“纳土归宋”，使东南免遭兵燹而保全江南水乡繁华。此前太平兴国二年三月太宗诏李昉等集文士编纂大型类书《太平总类》（983年成书千卷，赐名《太平御览》）及小说总集《太平广记》五百卷（本年八月成书）。",
