          "detail": "太平兴国四年正月宋太宗亲统潘美等大军北伐太原，击退辽援军，五月甲申北汉主刘继元出降（太宗命毁太原旧城改治唐明镇），五代十国分裂割据局面彻底终结。六月宋太宗不顾将士疲敝乏赏，自太原乘胜移师东进欲一举收复石敬瑭所割燕云十六州，连下易、涿二州合围辽南京幽州（今北京）；七月甲申，辽景宗遣耶律沙、耶律休哥、耶律斜轸精骑驰援，于幽州城西高梁河（今北京西直门外）两翼夹击大破宋军，太宗股中两箭乘驴车仓皇南遁，宋辽由此展开二十五年拉锯战。",
