          "detail": "雍熙三年正月，宋太宗乘辽圣宗年幼、萧绰（萧太后）临朝，命曹彬、崔彦进出东路雄州，田重进出中路飞狐，潘美、杨业（杨继业）出西路雁门，三路大举北伐收复燕云。东路曹彬孤军冒进克涿州后粮绝退师，五月于岐沟关（今河北涿州西南）遭萧太后与耶律休哥铁骑追歼大溃；西路奉诏护云、应四州百姓内迁，七月潘美、监军王侁违约弃陈家谷口接应阵地先遁，老将杨业率帐下血战至暮身被数十创，马重伤被辽军耶律斜轸俘获，绝食三日壮烈殉国，北宋自此由战略进攻全面转入战略防御。",
