          "detail": "北宋灭后蜀后尽括蜀地财帛入汴，复设博买务垄断蜀锦贸易，兼之连岁大旱。淳化四年二月，青城县茶农王小波聚众起义，向贫苦茶农疾呼：“吾疾贫富不均，今为汝均之！”（中国历史上首次明确提出“均贫富”经济纲领），十日间众至数万；十二月王小波战伤牺牲，众推其妻弟李顺为帅，翌年正月攻克成都建立“大蜀”政权改元应运（五月城破被杀，余部张余转战至995年）。",
