          "title": "北宋正式分全国为“十五路”，确立路—州（府、军、监）—县三级地方监司体制",
          "detail": "至道三年八月（三月宋太宗崩，太子赵恒即位为宋真宗），朝廷正式将全国疆域划分为京东、京西、河北、河东、陕西、淮南、江南、荆湖南、荆湖北、两浙、福建、西川、峡、广南东、广南西“十五路”（仁宗、神宗时析为十八路、二十三路）。每路不设单一行政长官，而分置转运使（漕司，掌财赋）、提点刑狱公事（宪司，掌司法监察）、安抚使（帅司，掌兵民）及提举常平司（仓司），互不统属、各自直接奏事中央。",
