          "title": "澶渊之盟：寇准力劝宋真宗亲征渡河御辽，宋辽缔约开启百二十年和平互市",
          "detail": "景德元年闰九月，辽圣宗与承天太后萧绰亲统二十万铁骑绕过河北坚城长驱南下，十一月直抵黄河岸边重镇澶州（今河南濮阳），开封震动；王钦若请奔金陵、陈尧叟请奔成都，唯宰相寇准力排众议，联殿前都指挥使高琼力拥宋真宗北上渡过黄河，御驾登澶州北城楼展示黄龙大旗，宋军欢声雷动，此前威虏军床子弩更射杀辽统帅萧挞凛。辽军锐气受挫遂遣宋降臣王继忠议和，十二月曹利用赴辽营达成“澶渊之盟”（明年正月换约）：宋辽约为兄弟之国（辽圣宗称宋真宗为兄），宋每年输辽“岁币”银十万两、绢二十万匹，双方以白沟河为界罢兵开设雄州等榷场互市，换来此后宋辽间百二十年边境和平。",
