          "title": "宋辽互换誓书正式落实澶渊盟约，于河北雄州、霸州、安肃军重开边境“榷场”互市",
          "detail": "继前年底澶州议和后，景德二年（辽统和二十三年）正月宋辽互遣使臣正式换约，宋廷在河北沿边雄州、霸州、安肃军、广信军相继恢复并扩建官办边境贸易市场——“榷场”（辽方亦于涿州、振武军等处设榷场对口互市）。北宋输出丝绸、茶叶、瓷器、漆器、香药与儒家典籍（严禁铜钱、硫磺焰硝与兵书出境），换取契丹良马、羊群、银两、毛皮与北珠，榷场岁入丰厚，奠定宋辽百余年经济互补格局。",
          "category": "经济民生",
          "regionId": "hebei",
