          "detail": "辽圣宗自1010年起屡次兴兵伐高丽以断高丽联宋后顾之忧。开泰七年十二月辽萧排押统军十万第三次渡鸭绿江直逼开京，开泰八年（宋天禧三年）二月回师渡茶、陀二水时遭高丽名将姜邯赞于龟州设伏阻击受挫；翌年高丽显宗王询审度国力，正式遣使向辽奉表称藩纳贡、停用宋年号而改行辽开泰正朔，辽圣宗亦册封王询为高丽国王，辽丽边境此后百余年不复交兵，高丽与北宋则继续保持海上文化商贸往来。",
