          "detail": "宋初四川专用笨重铁钱（大钱十贯重六十五斤），成都富商王昌懿等十六户遂联保印造私“交子”代钱流通，后因富商资产衰落无力兑现引发诉讼纷争。天圣元年十一月戊午，朝廷采益州知州薛田与转运使张若谷奏议，废禁私交子，正式于益州（成都）置“益州交子务”，由国家以铁钱三十六万缗为准备本钱，分界（每界三年一兑）印造发行官“交子”百二十五万六千三百四十缗，开创人类货币史上政府发行法定纸币之先河。",
