          "detail": "景祐三年，继任夏王之党项首领元昊命大臣野利仁荣仿汉字楷书结构创制笔繁形方之“西夏文”（番书十二卷共六千余字），下令国中艺文诰牒一律用番书书写，设蕃学与汉学并译儒家《孝经》《尔雅》及大批藏汉佛典。同年元昊统兵西击甘州、沙州回鹘，连克瓜（今甘肃瓜州）、沙（今敦煌）、肃（今酒泉）三州，囊括河西走廊全境，完全切断北宋与西域之陆路走廊。",
