          "detail": "宝元元年十月甲戌（十一日），党项平夏部首领元昊（嵬名曩霄）于兴庆府（今宁夏银川）南郊筑坛受册，正式即皇帝位（夏景宗），国号“大夏”（自号邦泥定国，史称西夏），改元天授礼法延祚；仿唐宋官制置中书省掌政务、枢密院掌兵权、三司掌财政及御史台、十六司，建十八监军司统全国精骑。元昊遣使奉表请北宋承认其帝号，宋廷下诏削夺元昊官爵赐姓、悬赏捉拿并断绝边关互市，持续五年之宋夏大战全面爆发。",
