          "detail": "熙宁三年十二月王安石拜同中书门下平章事（宰相）。熙宁四年二月丁巳，朝廷颁诏改革科举与学校：罢废进士诗赋、帖经、墨义及明经诸科，改以经义、论、策试进士，并于太学全面推行外舍、内舍、上舍递升考核之“太学三舍法”。同年十月壬子，正式向全国推行司农寺拟定之“募役法”（免役法）：废除民户按等第轮充州县衙前等破产重役，改按户等高下出“免役钱”（原享有免役特权之官户、寺观、女户亦须减半出“助役钱”），由官府雇人充役，解放自耕农人身束缚。",
