          "detail": "前一年冬交趾李朝辅政太尉李常杰乘宋廷专力西北，悍然率舟师十万突袭连陷宋钦州、廉州，围攻邕州四十二日破城屠杀知州苏缄及军民五万八千余人。熙宁九年二月宋神宗命老将郭逵为安南道招讨使、赵卨为副，统大军南下反击；十月王安石因爱子王雱病逝及新党内部分裂第二次罢相，判江宁府退隐半山潜心“荆公新学”。十二月郭逵大军收复广源州直抵富良江（今越南红河），以机石强弩击毁交趾战象与水师洪舰，交趾主李乾德惧而奉表谢罪归还掳民，宋越边界复归安定。",
