          "detail": "元丰八年三月宋神宗崩，十岁哲宗赵煦即位，宣仁圣烈高太皇太后垂帘听政，召司马光自洛阳入朝。元祐元年二月司马光拜尚书左仆射兼门下侍郎（宰相），抱病于数月间雷厉风行废罢保甲、方田、市易、青苗及免役法（中书舍人苏轼、同知枢密院范纯仁力陈免役与差役各有利弊，请缓改择善，司马光不听，限五日尽复差役）；四月王安石忧卒于江宁，九月司马光病卒于相位。元祐旧党旋即分裂为洛党（程颐）、蜀党（苏轼）、朔党（刘挚），北宋政坛深陷意气排击之新旧党争漩涡。",
