          "detail": "居住白山黑水之生女真完颜部受辽朝严酷盘剥（岁贡名鹰“海东青”，辽银牌天使横暴索贿）。政和四年（辽天庆四年）九月，完颜部都勃极烈完颜阿骨打集结诸部精骑二千五百人于来流水誓师起兵反辽，一举攻克辽东北边防重镇宁江州；十一月辽发兵十万（一说数万）渡混同江进剿，阿骨打乘夜雪狂风奇袭，于出河店（今黑龙江肇源西南）以三千七百骑击溃辽军主力，缴获车马甲兵无数，并定制“三百户为谋克，十谋克为猛安”，确立女真兵民合一之“猛安谋克”基本制度。",
