          "detail": "绍兴四年二至三月，完颜宗弼、完颜杲复率十万大军猛攻入蜀门户仙人关（今甘肃徽县东南），吴玠、吴璘浴血苦战大破金军，金人自此不敢再窥蜀道。同年五至七月，针对伪齐刘豫盘踞荆襄威胁长江中游，三十二岁之镇南军承宣使岳飞奉命率岳家军自江州渡江北伐，严明“冻死不拆屋，饿死不掳掠”军纪，连克郢州、随州（牛皋生擒王嵩）、襄阳府、唐州、邓州、信阳军，仅三个月收复“襄阳六郡”，打通川陕与江南联系并建立北伐前进基地（南宋于绍兴八年正式定“行在”于临安府即今杭州）。",
          "category": "军政征伐",
