          "detail": "自建炎四年（1130）鼎州钟相以“等贵贱、均贫富”起义建大楚政权，钟相牺牲后杨么（杨太）联合夏诚等依托洞庭湖水网建造脚踏轮桨巨型“车船”数十艘，屡败官军历时五年。绍兴五年六月，荆湖南北襄阳府路制置使岳飞奉命进讨：先遣使招降黄佐等瓦解水寨，继采智计自上游漂流巨木腐草填塞浅港，诱出杨么车船使其轮桨缠死失灵，宋军乘机投石纵火猛攻，仅用八日悉平洞庭水寨，收编五万少壮精兵充实岳家军水师，老弱散归田亩。",
