          "detail": "绍兴八年二月壬戌，宋高宗自建康返回临安府（今浙江杭州），自此正式定驻临安长达一百三十八年（名义仍尊开封为东京，称临安为“行在所”，以示不忘恢复中原，实为南宋国都）。同年北方金熙宗完颜亶改元“天眷”，在宗磐、韩企先等辅佐下颁行全面汉化官制改革——“天眷新制”：彻底废除女真初起贵族议事之谙班勃极烈旧制，正式确立尚书、中书、门下三省六部台院中央官制，并于上京建孔庙、封孔子四十九代孙孔璠为衍圣公。",
