          "detail": "绍兴十年五月，金都元帅完颜宗弼撕毁归还河南旧约分四路南侵；六月东京副留守刘锜率不足二万“八字军”死守顺昌（今安徽阜阳），冒酷暑以长斧斫马足大破宗弼十万精锐（顺昌大捷）。湖北京西宣抚使岳飞随即挥师全面北伐收复蔡、颖、陈、郑州，七月己酉于郾城之战令背嵬军持麻扎刀入阵上砍敌兵、下砍马足，大破宗弼一万五千重装“铁浮图”与左右翼“拐子马”；七月壬戌岳云、王贵复于颍昌血战再破金主力，前锋进抵距开封仅四十五里之朱仙镇，河北义军纷起响应。然宋高宗与宰相秦桧一心求和且深忌武将北伐迎回钦宗，先撤两淮友军使岳飞孤立，继发御札（金字牌）严令退兵，岳飞悲泣东向再拜曰：“十年之力，废于一旦！”",
