          "detail": "完颜宗弼致书秦桧“必杀飞，始可和”。绍兴十一年四月，宋高宗与秦桧借柘皋战后论功行赏，召韩世忠、张俊任枢密使，岳飞任枢密副使，罢宣抚司使其部曲直隶三省枢密院（御前诸军），一举收夺抗金三大将兵权。八月罢岳飞枢密副使，十月秦桧指使谏官万俟卨、罗汝楫与张俊联手逼诱王俊诬告张宪、岳云谋反以还岳飞兵权；韩世忠质问秦桧罪证，桧答“飞子云与张宪书虽不明，其事体莫须有”，世忠愤斥“‘莫须有’三字，何以服天下！”十二月癸巳除夕夜（公历1142年1月27日），三十九岁岳飞被赐死于临安大理寺狱，岳云、张宪弃市。",
