          "detail": "绍兴十一年十一月宋金议定和约条款，杀害岳飞后，绍兴十二年三月金熙宗遣左副元帅完颜宗弼之使臣萧毅等携衮冕册封宋高宗：“册尔构为大宋皇帝”，八月金放归高宗生母韦太后及宋徽宗灵柩，绍兴和议全面换约生效：一、南宋对金称臣（国书奉表称“臣构”）；二、划定宋金边界，东以淮水中流、西以大散关（今陕西宝鸡西南）为界，南宋割唐、邓二州及商、秦二州之半（包括和尚原）予金；三、南宋每年向金输纳“岁贡”银二十五万两、绢二十五万匹。自此宋金形成长达九十余年之淮水—秦岭南北对峙局面，秦桧独相专政十七年。",
