          "detail": "弑金熙宗自立之海陵王完颜亮（天德元年1149即位）深通汉学，力图摆脱上京女真旧贵族掣肘并进窥江南。天德三年命梁汉臣、张浩仿北宋东京汴梁宫阙制度扩建燕京城；天德五年（宋绍兴二十三年）三月辛亥，完颜亮率百官皇室正式自黑龙江阿城金上京迁入燕京，以燕京“乃天地之中”改名“中都”，升析津府为大兴府，改上京会宁府仅称会宁府（1157年更拆毁会宁旧宫殿），改元贞元。北京由此从历代北方军事重镇、辽陪都正式跃升为统治半壁中国之帝国首都，奠定金中都—元大都—明清北京一脉相承之建都格局。",
          "category": "典章制度",
          "regionId": "youyan",
          "source": "《金史·海陵纪》《地理志上》",
