          "detail": "南渡之初临安商户曾私发便钱会子；绍兴三十年二月，南宋朝廷采户部侍郎钱端礼奏议，正式将纸币发行权收归中央户部，设立“行在会子务”（后改隶都茶场），用徽州、池州特造楮皮纸印造官办“东南会子”（初发一贯、二贯、三贯三等，隆兴元年增印二百、三百、五百文小钞），以铜钱及茶盐香矾引为称提准备金，流通两浙、江东西、淮南并允许输纳税赋。自此“会子”与川引、淮交、湖会共同构成南宋纸币与铜钱并行之财政支柱。",
