          "title": "采石矶大捷：虞允文临危统水师大破金主完颜亮南侵大军；金世宗辽阳即位开启“大定之治”",
          "detail": "绍兴三十一年（金正隆六年）九月，金海陵王完颜亮不顾举国怨沸，亲统六十万大军分四道南侵欲一举灭宋（此前山东爆发耿京辛弃疾抗金起义，十月丁未金东京留守完颜雍乘虚于辽阳即帝位为金世宗，改元大定）。十一月完颜亮大军抵和州欲自采石矶（今安徽马鞍山西南）抢渡长江，宋主帅王权逃遁、军无统帅；奉命劳军之中书舍人虞允文毅然以文臣立江岸集结宋军一万八千人，命海鳅船踏车疾驶冲撞金舟、并发霹雳炮（纸壳石灰硫磺火器）大破金渡江水师（同月李宝水师亦于胶西唐岛火攻歼灭金舰队）。完颜亮移军瓜洲渡限明日渡江，十一月乙巳遭哗变部将完颜元宜射杀焚尸，金军北撤。",
