          "title": "“隆兴和议”订立：宋金改君臣为“叔侄之国”并核减岁币，南宋进入“乾淳之治”",
          "detail": "隆兴元年五月张浚督李显忠、邵宏渊发动“隆兴北伐”，初克灵壁、宿州，旋因二将不协在金帅纥石烈志宁反击下溃于符离；主和派汤思退复相撤防，金军渡淮进逼。隆兴二年十二月丙申（翌年乾道元年换约），宋孝宗与金世宗正式订立“隆兴和议”：一、废除绍兴和议南宋称臣旧礼，宋金改称“叔侄之国”（金世宗为叔大金皇帝，宋孝宗为侄大宋皇帝），改诏表为往来国书；二、改“岁贡”为“岁币”，岁减银绢各五万（定银二十万两、绢二十万匹）；三、疆界仍依绍兴旧界。此后南北维持四十余年休战，孝宗在位乾道、淳熙年间整顿东南会子纸币、兴修水利，江南经济文化高度繁荣，史称“乾淳之治”。",
