          "detail": "淳熙二年五月，浙东学者吕祖谦为会通学术异同，邀请集北宋二程洛学大成之朱熹与倡“心即理”之江西金溪陆九龄、陆九渊兄弟相会于信州铅山鹅湖寺（史称“鹅湖之会”）。陆氏兄弟赋诗直抒“易简工夫终久大，支离事业竟浮沉”，主张认识本心、尊德性为先；朱熹则坚持“性即理”，主张须经由今日格一物、明日格一物之“道问学”博学审思方能豁然贯通。双方论辩三日各持己见而互相敬重，成为中国宋明哲学史上程朱“理学”与陆王“心学”双峰并立辩难之标志性起点。",
