          "detail": "淳熙六年朱熹就任知南康军，寻访五代南唐国学旧址庐山五老峰下荒废之白鹿洞，奏请朝廷赐国子监经书，于淳熙七年三月修复落成“白鹿洞书院”（翌年陆九渊亦受邀登坛讲“君子喻于义，小人喻于利”章）。朱熹亲订《白鹿洞书院揭示》（学规）：列父子有亲等“五教之目”，明“博学之、审问之、慎思之、明辨之、笃行之”为学五序，倡“正其谊不谋其利，明其道不计其功”，摒弃单纯应举功利而重人格涵养，成为后世东亚书院共同尊奉之精神宪章。",
