          "detail": "南宋建炎二年（1128）杜充曾于滑州人为决河阻金致河道紊乱。绍熙五年（金章宗明昌五年）八月，黄河在阳武故堤（今河南原阳东南）发生历史性大决口，滔天洪水灌封丘而东，分南北两股：北清河入海仅分水十之二三，南股主流浩荡南下汇入泗水，在清口全面侵夺淮河下游河道东注黄海，史称“黄河夺淮”。此后直至1855年铜瓦厢决口北徙，黄河夺淮达661年之久，巨量泥沙淤高淮河河床，导致淮水郁积成洪泽湖、苏北海岸线外推数十公里，江淮水利与漕运格局彻底巨变。",
