          "detail": "绍熙五年宋光宗拒不主持孝宗丧礼，宗室宰相赵汝愚联外戚韩侂胄请太皇太后吴氏垂帘拥立宋宁宗；事成韩侂胄因未获实权怨恨，罗织罢逐赵汝愚（暴卒永州），并迁怒声援赵汝愚之道学名士。庆元二年八月丙辰，韩侂胄操纵台谏正式下诏禁绝“伪学”，规定科举贡士须具结“不是伪学”方许应试，落朱熹秘阁修撰官职（庆元四年更定赵汝愚、留正、朱熹、彭龟年、陈傅良、叶适等五十九人为“伪学逆党籍”），史称“庆元党禁”。庆元六年（1200）三月，完成《四书章句集注》之理学宗师朱熹于禁令未解中病逝于建阳考亭。",
