          "detail": "金初法制简略多参用宋辽旧律；金章宗即位后命司空襄、左丞完颜匡等详定新律，历时数载，于泰和元年十二月丁酉正式颁布《泰和律义》十二篇、三十卷、五百六十三条（同时颁行《律令》二十卷、《新定敕条》三卷、《六部格式》三十卷，统称“泰和律令”，翌年五月施行）。该法典以《唐律疏议》十二篇体例为骨干，结合北方女真、契丹、汉人社会经济实况增损百余条，成为宋金元法制演进之关键枢纽（元初未立新律前曾长期参用泰和律断狱）。",
