          "detail": "专权日久之平章军国事韩侂胄欲立盖世奇功巩固权位（1204年追封岳飞为鄂王、1206年四月追夺秦桧王爵改恶谥“缪丑”鼓动舆情），不听辛弃疾、华岳等军备未熟切谏，于开禧二年五月丁亥正式下诏伐金（“开禧北伐”）。宋军初克泗州，旋因将庸兵骄于宿州、寿春惨败；金军九路渡淮反扑围楚州、陷和州，四川宣抚副使吴曦更于兴州公然叛宋受金册封为蜀王（翌年二月为忠义士安丙诛杀），南宋被迫罢兵求和。",
