          "detail": "金人以索首谋韩侂胄头颅为议和要挟，开禧三年十一月礼部侍郎史弥远密联杨皇后与荣王赵璩，遣殿前司夏震于玉津园侧截杀上朝之韩侂胄。嘉定元年四月史弥远将韩侂胄、苏师旦首级开棺斩函送交金军；九月己未，宋金正式订立“嘉定和议”：一、宋金由叔侄之国降格为“伯侄之国”（金章宗为伯，宋宁宗为侄）；二、岁币由银绢各二十万增至银三十万两、绢三十万匹，另纳犒军银三百万两；三、金归还大散关、濠州等新占城池。史弥远旋拜右丞相，独揽南宋朝权二十六年。",
