          "detail": "窝阔台汗自北路渡河，命皇弟拖雷统四万精骑自宝鸡强借宋境汉中迂回出唐、邓北进包抄。绍定五年（金哀宗天兴元年）正月丁酉，拖雷与北路蒙古军会师，乘连日大雪严寒将饥疲交困之金完颜合达、移刺蒲阿十五万主力合围歼灭于钧州三峰山（今河南禹州西南），金名将良兵损失殆尽。三月速不台围攻开封，金守将赤盏合喜督军以生铁外壳装填火药之爆炸火器“震天雷”（声闻百里，铁甲皆透）及喷火“飞火枪”死守十六昼夜击退蒙军强攻；岁末城中粮绝，金哀宗弃城东走归德、蔡州。",
