          "detail": "端平元年（金天兴三年）正月戊申，蒙古塔察儿军与南宋名将孟珙、江海所统两万荆鄂宋军（运粮三十万石助蒙）夹击攻破蔡州（今河南汝南），金哀宗完颜守绪传位于统帅完颜承麟后自缢于幽兰轩，承麟即位未毕即死于乱兵，立国百二十年之金朝灭亡。金亡后，宋相郑清之与淮帅赵范、赵葵兄弟急功轻敌，不顾乔行简、孟珙谏阻，于六月出兵抢占残破空城开封与洛阳（“端平入洛”）；八月蒙古军南下决黄河寸金淀灌宋营并断粮道，入洛宋军大溃，窝阔台遂于年底下诏以宋败盟为由分三路大举伐宋，宋蒙（元）长达四十五年之大战全面爆发。",
