          "detail": "端平二年（窝阔台汗七年）春，窝阔台于漠北鄂尔浑河畔建成哈拉和林城（万安宫）作为大蒙古国首都，召开忽里勒台大会：除三路攻宋外，命术赤次子拔都为统帅、老将速不台为先锋，率察合台、窝阔台、拖雷各系宗王长子共十五万大军发动“长子西征”（1235—1242）：连克伏尔加保加尔、钦察草原及莫斯科、弗拉基米尔、基辅等罗斯诸公国，1241年春分兵大破波兰—日耳曼条顿骑士联军（里格尼茨之战）与匈牙利国王贝拉四世主力（蒂萨河之战），前锋逼近维也纳，冬闻窝阔台崩讯东返，于伏尔加河下游萨莱建钦察汗国（金帐汗国）。",
