          "detail": "蒙古灭金战争中大量中原儒生沦为战俘家奴（“驱口”），文脉几绝。蒙古窝阔台汗九年（丁酉年）八月，中书令耶律楚材与名臣术忽德、刘中力请开科取士，获准命断事官术忽德与山西东路课税使刘中赴诸路考试儒士（次年戊戌年揭晓，史称“丁酉科试”或“戊戌选试”）：试以经义、词赋、论三科，共录取合格儒士四千零三十人，其中被俘为奴者一千余人由官府赎免为“儒户”免除赋役，委充各路议事官及地方学校教官，为元初许衡、姚枢等北方理学复兴保住了珍贵火种。",
