          "detail": "据全书跋尾明确纪年“大聚会着，鼠儿年七月，写毕于客鲁涟河之阔迭额阿剌勒行宫”（学界主流考定此“鼠儿年”即窝阔台汗十二年庚子年1240，一说成书于1228戊子年并于1240或1252续补窝阔台纪事），蒙古宫廷史官以畏兀儿体蒙古文撰成十二卷（或十五卷）《忙豁仑·纽察·脱卜察安》（汉译《元朝秘史》）。全书自成吉思汗远祖苍狼白鹿谱系叙起，详实生动记载铁木真童年磨难、统一草原、建千户怯薛军政制度及窝阔台即位施政，融草原英雄史诗与第一手宫廷实录于一炉（明洪武初年翰林院以汉字音译并附旁译总译刊存）。",
