          "detail": "自1236年阔端破成都后，川蜀平原州县屡遭蒙古铁骑残破。淳祐二年十二月宋理宗擢余玠任四川安抚制置使兼知重庆府；淳祐三年，余玠筑招贤馆礼聘播州隐士冉琎、冉璞兄弟，采其“徙合州城于钓鱼山”奇策，依托嘉陵江、渠江、涪江三江汇流悬崖绝壁筑起坚不可摧之合州“钓鱼城”（今重庆合川东），并在全蜀水道要冲联动修筑云顶、青居、大获、苦竹、白帝等二十余座山城寨堡，城内掘井垦田、兵民相守，成功遏制蒙古骑兵机动优势达三十余年。",
