          "title": "“凉州会谈”：蒙古皇子阔端与西藏高僧萨迦班智达会晤发致藏区书，开启西藏纳入中央版图先声",
          "detail": "镇守西凉之窝阔台次子阔端久闻西藏萨迦派第四祖萨迦班智达·贡噶坚赞学贯五明、德望崇隆，于1244年遣使入藏奉书礼请。淳祐六年萨迦班智达携十岁侄八思巴等抵凉州，淳祐七年（贵由汗二年）春自西域返镇之阔端与萨迦班智达于凉州（今甘肃武威）正式举行历史性会谈。萨迦班智达向卫藏阿里各教派僧俗首领发出《萨迦班智达致蕃人书》，陈述蒙古国力强盛与宗教宽容政策，商定西藏各地归顺贡赋户口清册，为十余年后元朝设立总制院（宣政院）直接行使对西藏主权奠定基石。",
