          "detail": "淳祐七年冬，四任提点刑狱官之建阳法医学家宋慈在湖南提刑任上博采前代检验书并融汇自身二十余年疑狱复勘经验，撰成《洗冤集录》五卷五十三条刊刻颁作诸路检验官圭臬，系统确立尸体现象、自缢与假自缢、生前溺水与死后抛尸、火烧与焚尸、中毒急救与验骨法等科学鉴别规范，比欧洲1602年意大利费德罗法医书早三百五十余年。同年九月，数学家秦九韶完成《数书九章》十八卷，提出任意高次方程数值解法“正负开方术”及求解一次同余式组之“大衍求一术”（中国剩余定理），把宋元算学推向世界巅峰。",
