          "detail": "蒙古宪宗蒙哥汗即位后采皇弟忽必烈战略大迂回方案，命忽必烈统军、大将兀良合台总军事，于1252年秋自陕西临洮南下，穿越川西甘孜松潘二千余里崇山雪岭直插云南。宝祐元年（蒙哥汗三年）十月，大军抵金沙江畔，乘夜间以牛羊皮浑脱皮筏（“革囊”）抢渡天险，大破大理守军；忽必烈采儒臣姚枢“止杀”谏言（制止杀幡分驰诸军），十二月兵不血刃招抚大理国都羊苴咩城（今云南大理），生擒权臣高泰祥与大理王段兴智，延续三百一十七年之大理国灭亡，云南自南诏以来重归统一王朝直接经略。",
