          "detail": "蒙哥大汗分兵三路发动灭宋总攻：忽必烈渡淮攻鄂州、兀良合台自云南交趾北上湖南，蒙哥亲统主力四万（号十万）入蜀顺嘉陵江南下。开庆元年二月，蒙哥大军合围合州钓鱼城（今重庆合川东），南宋知合州王坚与副将张珏率军民依托峭壁城防浴血死守五个月，前锋元帅汪德臣中飞石毙命。七月癸亥（公历8月11日），蒙哥汗在城下督战受创（一说中炮石重伤、一说军中暑痢疫发），暴崩于温汤峡行营！围鄂州之忽必烈急与宋贾似道议和北返争位，西征叙利亚之旭烈兀主力亦东撤，钓鱼城军民以一城之力扭转了欧亚大陆全局历史走向。",
