          "detail": "蒙哥崩后，统握汉地重兵之皇弟忽必烈采汉儒郝经、刘秉忠、许衡、姚枢“先立定基”之策，于景定元年三月辛卯在开平（今内蒙古正蓝旗东，1263年定名上都）自行召集大会即大汗位（幼弟阿里不哥亦于和林称汗，双方激战四年至1264年平定）。五月戊辰，忽必烈打破蒙古汗国无年号旧例，仿中原王朝建元“中统”，正式设立中书省总领政务、十路宣抚司治地方；十月发行全国统一纸币“中统元宝交钞”，十二月封藏传佛教萨迦派高僧八思巴为国师，全面确立“行汉法”立国方针。",
