          "detail": "景定五年（至元元年）七月，漠北阿里不哥率诸王赴上都归降，蒙古汗位内战结束；八月丁巳，忽必烈采刘秉忠奏议，以燕京“龙盘虎踞，形势雄伟，南控江淮，北连朔漠”，诏改燕京为中都，大赦改中统五年为至元元年。同年朝廷正式设立与中书省、枢密院并列之中央专门机构“总制院”（以国师八思巴领之，至元二十五年1288正式改名“宣政院”），统掌全国佛教事务并直接管辖吐蕃（西藏）全境之设官、清查户口（吐蕃十三万户）、驿站与驻军，标志着西藏正式纳入中国中央政府直接行政管辖。",
