          "detail": "忽必烈以回鹘式蒙古文字母未尽精确且难兼拼诸族语音，命国师八思巴创制新国字。至元六年（宋咸淳五年）二月己丑，八思巴仿藏文字母方体结构创制之四十一字母音素拼音文字“蒙古新字”（俗称“八思巴字”）告成，忽必烈下诏颁行天下：“自今以往，凡有玺书颁降，并用蒙古新字，仍各以其国字副之”，升八思巴为大宝法王（帝师），各路府州增设蒙古字学，现存元代圣旨碑、官印、钞版与牌符均镌刻此字。",
