          "detail": "自1267年起元军阿术、刘整筑长围造水师死困南宋长江中游屏障襄阳、樊城长达六年，宋援军张顺、张贵乘轮船死战殉国。至元九年末，伊利汗国遣西域炮匠阿老瓦丁、亦思马因赴襄阳前线造巨型配重式杠杆抛石机“回回炮”（一发重百五十斤，声震天地，入地七尺）；至元十年正月癸亥攻破樊城，宋将范天顺自缢、牛富率死士肉搏投火壮烈殉国；二月丁未，孤守襄阳六年援绝之吕文焕在阿里海牙招谕下献城降元，南宋江汉防线由此全面崩溃。",
