          "title": "芜湖丁家洲之溃贾似道十三万宋军覆没；威尼斯青年马可·波罗经丝路抵元上都觐见忽必烈",
          "detail": "德祐元年（至元十二年）二月庚申，南宋权相贾似道被迫督水陆精兵十三万屯芜湖鲁港丁家洲阻击元帅伯颜；元军两岸架巨炮轰击宋舰、阿术率轻舟横击，前锋孙虎臣惊溃，贾似道仓皇鸣金乘小船遁逃扬州，十三万宋军不战自溃，建康、镇江相继失守，文天祥于赣州散家财招募义兵入卫。同年夏（约五月），意大利威尼斯商人尼古拉·波罗、马菲奥·波罗携二十一岁之马可·波罗历时三年半穿越帕米尔与河西走廊抵达元上都（开平）觐见忽必烈，此后留居元朝十七载游历大都、杭州、泉州各地，返欧后由鲁斯蒂谦笔录《马可·波罗行纪》（《寰宇记》），激起欧洲探索东方之热潮。",
          "category": "对外交流",
          "regionId": "jiangdong",
