          "title": "元丞相伯颜进驻皋亭山，南宋谢太皇太后奉玺出降，元军入临安并全面推行“行省制”",
          "detail": "德祐元年二月贾似道十三万宋军在芜湖丁家洲不战自溃，赣州知州文天祥毁家起兵勤王；至元十三年（景炎元年）正月，元中书右丞相伯颜统三路大军进屯临安城北三十里皋亭山。南宋谢太皇太后与全太后携五岁宋恭帝赵㬎奉传国宝玺上表降元（右丞相文天祥赴元营慷慨抗争被扣，旋自镇江脱险赴温州联张世杰、陆秀夫拥立益王赵昰于福州为宋端宗）。二月伯颜整军和平入据临安，封存秘阁图书版籍户口，将恭帝母子北迁大都。伴随平定江南，元朝相继建立江淮（江浙）、江西、湖广等“行中书省”，地方最高行政体制“行省制”逐步推广全国。",
