          "title": "厓山海战：陆秀夫背负八岁少帝赵昺投海殉国，南宋灭亡，元朝完成全国大一统",
          "detail": "前一年十二月信国公文天祥在广东海丰五坡岭不幸被俘（过零丁洋留千古绝唱“人生自古谁无死，留取丹心照汗青”，1282年十二月于大都柴市凛然就义）。至元十六年正月，元汉军都元帅张弘范与李恒合兵围攻南宋流亡小朝廷最后基地新会厓山（今广东江门崖门海口），太傅张世杰将千余艘大船联结成海上连营死战拒降。二月癸未（初六日），张弘范乘潮水涨落南北夹击火攻，自晨至暮激战破宋水寨；左丞相陆秀夫见突围无望，杖剑驱妻子入海后，向八岁宋少帝赵昺泣拜曰：“国事至此，陛下当为国死！”遂背负少帝纵身跃入怒海殉国，后宫军民十余万人相继蹈海，张世杰突围遇飓风溺亡。立国三百二十年之两宋至此覆亡，元朝结束自唐末五代以来长达三百七十余年之多政权并立分裂，建立起北逾阴山岭北、南括南海、西及西域吐蕃、东尽辽左之空前大一统帝国。",
