          "title": "郭守敬、王恂主持“四海测验”修成《授时历》，定回归年为 365.2425 日与现行公历完全一致",
          "detail": "元世祖忽必烈命许衡总领，太史令王恂、都水监郭守敬共同负责改治新历。郭守敬打破旧浑仪环圈繁复遮蔽视线之弊，创制简仪、仰仪、景符及高达四丈之登封观星台高表等十余种精密天文仪器，并组织北起铁勒（北纬64度）、南抵南海（北纬15度）跨越近五十个纬度之全国二十七座观测所实施“四海测验”。至元十七年十一月新历告成，忽必烈取《尚书·尧典》“敬授民时”赐名《授时历》（翌年颁行，明代《大统历》沿用共行364年）：废除繁琐上元积年，应用三次差内插法与球面三角弧矢割圆术，精确测得回归年为 365.2425 日，与三百零二年后（1582）欧洲颁行之格里高利现行公历精度丝毫不差。",
