          "title": "元朝开凿山东“会通河”（继由郭守敬开凿通惠河），京杭大运河裁弯取直全线贯通；至元末置澎湖巡检司",
          "detail": "元定都大都后，亟需将江南数百万石漕粮北运京师。至元二十六年正月，忽必烈采韩仲晖等议发民夫开凿山东须城安山北至临清御河之“会通河”二百五十里（建船闸三十一座节水通航）；随后至元二十九至三十年（1292—1293），都水监郭守敬主持引昌平白浮神山泉水汇瓮山泊（今颐和园昆明湖），开凿自大都积水潭东至通州高丽庄之“通惠河”百六十四里，粮船自杭州可直驶大都城内积水潭，彻底截去隋唐大运河绕道洛阳之数百里弯路，定型今日“京杭大运河”走向，并与朱清、张瑄开辟之东海海运相辅而行。约在至元末年（据元汪大渊《岛夷志略》载“至元间立巡检司”，确年学界考定在1281—1294年间），元廷正式于泉州路晋江县下设“澎湖巡检司”，管辖澎湖与台湾民政海防。",
