          "detail": "灭宋一统后南北法制亟待划一，至元二十八年五月丁巳，忽必烈正式颁行中书右丞何荣祖整编之《至元新格》（分公规、选格、治民、理财、赋役、课程、仓库、造作、防盗、察狱十篇，为元代首部全国统一行政与司法单行法汇编）。同年十二月户部奏报全国在籍户一千三百四十三万余、口五千九百八十四万余（不含岭北、吐蕃、云南未入常籍人口）。伴随大都、杭州等商业都会勾栏瓦舍繁盛，大都太医院尹关汉卿（作《感天动地窦娥冤》《单刀会》六十余本）、王实甫（作《西厢记》）、白朴、马致远等才人贴近市井民生，将中国古典戏曲“元杂剧”推向黄金时代。",
