          "title": "农学家王祯刊行《农书》三十七卷，首创按韵拣字之木活字“转轮排字盘”",
          "detail": "皇庆二年，曾任安徽旌德、江西永丰县尹之山东东平农学家王祯正式刊印综合性农学巨著《农书》（全书分《农桑通诀》《百谷谱》《农器图谱》三集，首次融汇中国北方旱作与南方水田两套农学体系，精绘水排、水转大纺车等二百六十余幅机械农具图谱）。王祯并于书末详附《造活字印书法》，记载其改良胶泥活字易碎缺陷，创制轻便整洁之“木活字”三万余枚，并发明以大木轮分韵盛字、人坐两轮间旋转摘字之“转轮排字盘”，大幅提升活字排版效率。",
