          "detail": "依皇庆二年科举诏，延祐元年八月全国十七处试院举行首届乡试选合格举人三百名；延祐二年二月会试大都，三月乙卯元仁宗亲策贡士于大明殿，赐蒙古人护都答儿（赐名赵护都答儿）、汉人张起岩等五十六人进士及第、出身有差，中断近八十年之全国科举正式落地运行。同年朝廷采章闾奏议，遣使赴江浙、江西、河南三行省限期四十日自实田土（史称“延祐经理”），旨在括清豪强隐漏税粮，因地方官吏贪暴逼民虚报诱发江西赣州蔡五九民变，旋即下诏罢止并免三省自实田租二年。",
