          "detail": "元文宗深耽儒雅书画，前一年特于宫城西创设奎章阁学士院，延揽虞集、揭傒斯、柯九思等名儒鉴藏内府法书名画、讲论经史。至顺元年二月戊申，文宗命奎章阁大学士赵世延、侍书学士虞集等领衔，仿唐宋《会要》体例全面辑录有元一代政典法规，纂修《皇朝经世大典》（翌年五月全书告成，共八百八十卷、目录十二卷、公牍一卷、纂修通议一卷，分君事四篇、臣事六篇）。原书虽于明代散佚（部分收入《永乐大典》及《元文类》序录），然明初修《元史》诸志几乎全据此书剪裁而成。",
