          "title": "元顺帝联脱脱发动政变罢黜专权排汉之太师伯颜，年底下诏恢复科举，开启“至正更化”",
          "detail": "蔑儿吉台氏权臣伯颜自1335年独揽军政大权，悍然废罢科举、排斥汉儒，威权震主。后至元六年二月己亥，二十一岁之元顺帝妥懽贴睦尔与伯颜亲侄、御史大夫脱脱秘密定计，趁伯颜出京赴柳林围猎之机关闭大都城门，下诏削夺伯颜一切兵权，贬窜南恩州阳春县安置（行至江西龙兴路病死）。脱脱随即出任中书右丞相，大义灭亲尽革伯颜弊政：十二月甲戌正式下诏恢复中断六年之科举取士，昭雪冤狱、复行太庙四时祭礼、弛马禁减盐额，翌年改元至正，史称“至正更化”。",
