          "title": "贾鲁征民夫十五万堵塞黄河白茅决口；韩山童、刘福通于颍州发动元末红巾军大起义",
          "detail": "自1344年黄河决白茅堤泛滥山东盐场与会通河漕路，脱脱力排工部尚书成遵“聚十万饥民于大盗之乡恐生巨变”之警告，于至正十一年四月壬午命工部尚书贾鲁为总治河防使，征调汴梁、大名等十三路民夫十五万、庐州戍军二万，自黄陵冈疏凿新河二百八十里，沉石船二十七艘强塞故道合龙（“贾鲁治河”）。钞法崩坏叠加河工官吏克扣暴虐，五月辛亥，白莲教首领韩山童、刘福通预先散布“石人一只眼，挑动黄河天下反”民谣，于颍州（今安徽阜阳）颖上白鹿庄聚众三千人头裹红巾宰牛马起义（韩山童被捕牺牲，刘福通突围连克颍州、罗山、汝宁，拥众十万）；八月徐寿辉、彭莹玉、邹普胜于蕲水起义，十月建天完政权（改元治平），元末农民大起义席卷江淮。",
