          "detail": "至正十二年二月乙酉，定远豪族郭子兴与孙德崖等散家财聚壮士数千，乘夜袭据濠州（今安徽凤阳）响应红巾军。濠州钟离太平乡贫农出身（1344年淮北大旱蝗疫父母兄长相继饿死，入皇觉寺为僧游方淮西三年）之二十五岁青年朱元璋，收到同乡汤和来信邀约，于闰三月甲戌朔毅然投奔濠州郭子兴麾下充当步卒亲兵（九夫长）。朱元璋作战勇决且粗通文墨、礼贤下士，深获郭子兴信任并娶其养女马氏（后为明孝慈高皇后）；翌年返钟离故里招募徐达、周德兴、郭英等二十四将南略定远、滁州，逐渐形成独立精锐劲旅。",
