          "detail": "前一年冬右丞相脱脱统百万大军围攻高邮盐贩义军首领张士诚（1353年起兵泰州白驹场称诚王），外城已破旦夕可下；元顺帝偏信奸臣哈麻诬奏，于至正十四年十二月丁巳一纸诏书临阵削夺脱脱兵权（旋流放云南鸠杀），城下百万元军顷刻溃散，元朝中央彻底丧失机动野战主力。至正十五年二月己未，刘福通自砀山夹河迎韩山童之子韩林儿至亳州（今安徽亳州）即皇帝位（号“小明王”），定国号曰“大宋”，改元龙凤，成为北方与江淮红巾军共奉正朔（1357年分三路北伐曾焚毁元上都宫阙、进驻汴梁）。同年六月乙卯，朱元璋统徐达、常遇春自和州渡过长江，一举攻拔采石矶与太平路。",
