          "title": "朱元璋统军攻克江南重镇集庆路改名“应天府”，奠定逐鹿天下之江南核心根据地",
          "detail": "至正十六年二月张士诚渡江南下攻占富甲天下之平江路（苏州）。三月辛巳朱元璋自太平水陆并进直趋集庆路（今江苏南京），破陈兆先水营降精兵三万六千；三月庚寅（初十日）大军攻破集庆城，元江南行台御史大夫福寿巷战死。朱元璋入城召官吏父老宣布除元苛政、各安生业，改集庆路为“应天府”，置江南行中书省自领平章，礼聘刘基、宋濂、章溢、叶琛等浙东名儒（翌年攻下徽州时亲访老儒朱升，采纳其“高筑墙，广积粮，缓称王”九字大策），西御陈友谅、东制张士诚，由流动作战转向稳健政权建设。",
